package com.zenix.musicplayer;

import android.content.Context;
import android.util.AtomicFile;
import android.util.Base64;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

final class BackupManager {
    private final Context context;private final ZenixRuntime runtime;private final ListeningStats stats;private final AtomicFile journal;
    private JSONObject pending;private String token;private String failure="";
    BackupManager(Context context,ZenixRuntime runtime,ListeningStats stats){this.context=context;this.runtime=runtime;this.stats=stats;journal=new AtomicFile(new File(context.getFilesDir(),"backup-restore.json"));try{JSONObject saved=readJournal();if(saved!=null&&saved.optBoolean("pending")){Json.put(saved,"receiptId",saved.optString("receiptId",UUID.randomUUID().toString()));Json.put(saved,"recovered",true);Json.put(saved,"recoveryTarget","pending");Json.put(saved,"browserPending",false);writeJournal(saved);}else if(saved!=null&&saved.optBoolean("browserPending")){Json.put(saved,"browserPending",false);Json.put(saved,"recovered",true);Json.put(saved,"recoveryTarget","after");writeJournal(saved);}}catch(Exception e){failure="恢复快照无法读取，已保留文件："+Json.message(e);}}
    private JSONObject readJournal()throws Exception{try{return ProtectedJson.decode(new JSONObject(new String(SourceHttp.bounded(journal.openRead(),32*1024*1024),StandardCharsets.UTF_8)));}catch(FileNotFoundException e){return null;}}
    private void writeJournal(JSONObject value)throws Exception{byte[] bytes=ProtectedJson.encode(value.toString()).getBytes(StandardCharsets.UTF_8);if(bytes.length>32*1024*1024)throw new Exception("恢复快照过大，请分批恢复资料");FileOutputStream output=null;try{output=journal.startWrite();output.write(bytes);journal.finishWrite(output);}catch(Exception e){if(output!=null)journal.failWrite(output);throw e;}}
    private Set<String> sections(JSONArray values)throws Exception{if(values==null||values.length()==0)throw new Exception("请选择要备份或恢复的资料");Set<String> result=new LinkedHashSet<>();for(int i=0;i<values.length();i++){String key=values.getString(i);if(!BackupFormat.SECTIONS.contains(key))throw new Exception("资料类型无效");result.add(key);}return result;}
    private JSONArray browserSections(Set<String> selected){JSONArray result=new JSONArray();for(String key:selected)if(!key.equals("profile"))result.put(key);return result;}
    private JSONObject recoveryValues(JSONObject state,Set<String> selected)throws Exception{JSONObject result=new JSONObject();for(String key:List.of("liked","favorites","playlists","history"))if(selected.contains(key))Json.put(result,key,state.getJSONObject("personal").get(key));for(String key:List.of("stats","appearance","profile"))if(selected.contains(key))Json.put(result,key,state.getJSONObject(key));if(selected.contains("appearance"))Json.put(result,"cardTransparency",state.getJSONObject("profile").optDouble("cardTransparency",0));if(selected.contains("personalFeatures")){JSONObject value=state.getJSONObject("personalFeatures");Json.put(result,"personalFeatures",Json.obj("bookmarks",value.getJSONArray("bookmarks"),"lyrics",value.getJSONArray("lyrics")));}if(selected.contains("featureSettings")){JSONObject value=FeatureSettingsFormat.clean(state.getJSONObject("featureSettings"));for(String key:FeatureSettingsFormat.PARTS)Json.put(result,key,Json.obj("present",value.getJSONObject("present").optBoolean(key),"value",value.getJSONObject(key)));}return result;}
    private JSONObject captureSettings(JSONObject browser)throws Exception{
        if(browser!=null&&!browser.optString("settingsError").isEmpty())throw new Exception("功能设置无法读取，原设置已保留");JSONObject raw=new JSONObject(),present=new JSONObject(),space=runtime.store.object("spaceFeatures"),playback=runtime.store.object("playbackPreferences"),assistant=runtime.store.object("assistantUiSettings"),offline=runtime.store.object("offlineTasks");
        if(space!=null)Json.put(raw,"space",space);if(playback!=null)Json.put(raw,"playbackPreferences",playback);if(assistant!=null)Json.put(raw,"assistant",assistant);
        if(offline!=null&&offline.optJSONObject("policy")!=null)Json.put(raw,"networkPolicy",offline.getJSONObject("policy"));
        for(String key:FeatureSettingsFormat.PARTS)Json.put(present,key,raw.has(key));
        if(browser!=null&&browser.optJSONObject("settings")!=null){JSONObject renderer=FeatureSettingsFormat.clean(browser.getJSONObject("settings"));Json.put(raw,"assistant",renderer.getJSONObject("assistant"));Json.put(present,"assistant",renderer.getJSONObject("present").optBoolean("assistant"));}
        Json.put(raw,"present",present);return FeatureSettingsFormat.clean(raw);
    }
    private JSONObject recovery(JSONObject saved)throws Exception{
        boolean after=!saved.optBoolean("recovered")||saved.optString("recoveryTarget").equals("after");JSONObject target=saved.getJSONObject(after?"after":"before"),previous=saved.getJSONObject(after?"before":"after");
        return Json.obj("browser",target.optJSONObject("browser"),"previousBrowser",previous.optJSONObject("browser"),"sections",browserSections(sections(saved.getJSONArray("sections"))),"backendPending",saved.optBoolean("pending"),"browserReceipt",true,"receiptId",saved.optString("receiptId"),"undoAvailable",after&&!saved.optBoolean("finishedUndo"));
    }
    private JSONObject capture(Set<String> selected)throws Exception{runtime.store.ensureReadable();JSONObject state=runtime.store.readKeys("personal","profile","appearance","personalFeatures");if(selected.contains("featureSettings"))Json.put(state,"featureSettings",captureSettings(null));if(!state.has("personalFeatures"))Json.put(state,"personalFeatures",PersonalFeatureFormat.empty());if(!state.has("profile"))Json.put(state,"profile",new JSONObject());if(!state.has("appearance")||state.isNull("appearance"))Json.put(state,"appearance",Json.obj("completed",true,"background",JSONObject.NULL));Json.put(state,"stats",selected.contains("stats")?stats.exportAll():Json.obj("startedAt",System.currentTimeMillis(),"days",new JSONObject(),"tracks",new JSONObject()));return state;}
    private void writeState(JSONObject value,Set<String> sections)throws Exception{JSONObject changes=new JSONObject();if(sections.stream().anyMatch(key->List.of("liked","favorites","playlists","history").contains(key))){JSONObject personal=runtime.store.object("personal");for(String kind:List.of("liked","favorites","playlists","history"))if(sections.contains(kind))Json.put(personal,kind,value.getJSONObject("personal").get(kind));Json.put(changes,"personal",personal);}if(sections.contains("profile"))Json.put(changes,"profile",value.getJSONObject("profile"));else if(sections.contains("appearance")){JSONObject profile=runtime.store.object("profile");Json.put(profile,"cardTransparency",value.getJSONObject("profile").optDouble("cardTransparency",0));Json.put(changes,"profile",profile);}if(sections.contains("appearance"))Json.put(changes,"appearance",value.getJSONObject("appearance"));if(sections.contains("personalFeatures"))Json.put(changes,"personalFeatures",PersonalFeatureFormat.clean(value.getJSONObject("personalFeatures")));if(sections.contains("featureSettings")){JSONObject settings=FeatureSettingsFormat.clean(value.getJSONObject("featureSettings")),present=settings.getJSONObject("present");Json.put(changes,"spaceFeatures",present.optBoolean("space")?settings.getJSONObject("space"):JSONObject.NULL);Json.put(changes,"playbackPreferences",present.optBoolean("playbackPreferences")?settings.getJSONObject("playbackPreferences"):JSONObject.NULL);Json.put(changes,"assistantUiSettings",present.optBoolean("assistant")?settings.getJSONObject("assistant"):JSONObject.NULL);JSONObject offline=runtime.store.object("offlineTasks");if(offline==null)offline=Json.obj("schema",1,"tasks",new JSONArray());if(present.optBoolean("networkPolicy"))Json.put(offline,"policy",settings.getJSONObject("networkPolicy"));else offline.remove("policy");Json.put(changes,"offlineTasks",offline);}runtime.store.replaceAtomic(changes);if(sections.contains("stats"))stats.replaceAll(value.getJSONObject("stats"));}
    private JSONObject selected(JSONObject state,Set<String> sections)throws Exception{JSONObject result=new JSONObject();if(sections.stream().anyMatch(key->List.of("liked","favorites","playlists","history").contains(key)))Json.put(result,"personal",state.getJSONObject("personal"));for(String key:List.of("profile","appearance","stats","personalFeatures","featureSettings"))if(sections.contains(key))Json.put(result,key,state.getJSONObject(key));if(sections.contains("appearance"))Json.put(result,"cardTransparency",state.getJSONObject("profile").optDouble("cardTransparency",0));return result;}
    synchronized JSONObject preview(String text)throws Exception{pending=BackupFormat.decode(text);token=UUID.randomUUID().toString();JSONObject result=BackupFormat.preview(pending);Json.put(result,"token",token);if(pending.optJSONObject("extensions")!=null&&pending.getJSONObject("extensions").has("featureSettings"))Json.put(result,"settingsDiff",FeatureSettingsFormat.diff(captureSettings(null),pending.getJSONObject("extensions").getJSONObject("featureSettings")));return result;}
    synchronized String create(JSONObject args)throws Exception{if(!failure.isEmpty())throw new Exception(failure);Set<String> selected=sections(args.optJSONArray("sections"));JSONObject state=capture(selected);if(selected.contains("featureSettings"))Json.put(state,"featureSettings",captureSettings(args.optJSONObject("browser")));JSONObject payload=Json.obj("personal",new JSONObject());for(String key:List.of("liked","favorites","playlists","history"))if(selected.contains(key))Json.put(payload.getJSONObject("personal"),key,state.getJSONObject("personal").opt(key));if(selected.contains("profile"))Json.put(payload,"profile",BackupFormat.profile(state.getJSONObject("profile")));if(selected.contains("stats"))Json.put(payload,"stats",state.getJSONObject("stats"));if(selected.contains("appearance")){JSONObject appearance=Json.obj("transparency",args.optJSONObject("browser")==null?20:args.getJSONObject("browser").optDouble("transparency",20));JSONObject background=state.getJSONObject("appearance").optJSONObject("background");if(background!=null&&args.optBoolean("includeBackground")){String kind=background.optString("kind");if(kind.equals("video")&&!args.optBoolean("includeVideo"))throw new Exception("视频背景需要单独勾选");File file=ownedBackground(background.getString("url"));byte[] bytes=SourceHttp.bounded(new FileInputStream(file),(kind.equals("video")?32:12)*1024*1024);media(bytes,kind);Json.put(appearance,"media",Json.obj("kind",kind,"name",background.optString("name","自定义背景"),"base64",Base64.encodeToString(bytes,Base64.NO_WRAP)));}Json.put(payload,"appearance",appearance);}if(selected.contains("personalFeatures")){JSONObject extension=Json.copy(state.getJSONObject("personalFeatures"));Json.put(extension,"journal",new JSONArray());Json.put(payload,"extensions",Json.obj("personalFeatures",extension));}if(selected.contains("featureSettings")){JSONObject extensions=payload.optJSONObject("extensions");if(extensions==null)extensions=new JSONObject();Json.put(extensions,"featureSettings",state.getJSONObject("featureSettings"));Json.put(payload,"extensions",extensions);}return BackupFormat.encode(payload);}
    private File ownedBackground(String url)throws Exception{File file=new File(url).getCanonicalFile(),folder=new File(context.getFilesDir(),"background").getCanonicalFile();if(!file.getParentFile().equals(folder)||!file.isFile())throw new Exception("背景文件不可读取");return file;}
    synchronized void replaceBackground(JSONObject background,File file)throws Exception{
        if(!failure.isEmpty())throw new Exception(failure);
        // Read the journal before cleanup; a damaged snapshot must keep its files.
        JSONObject saved=readJournal();
        runtime.store.set("appearance",Json.obj("completed",true,"background",background));
        BackgroundFiles.prune(file.getParentFile(),file,saved);
    }
    static String media(byte[] bytes,String kind)throws Exception{String extension="";if(bytes.length>=12){if(bytes[0]==(byte)137&&bytes[1]==80&&bytes[2]==78&&bytes[3]==71)extension=".png";else if(bytes[0]==(byte)255&&bytes[1]==(byte)216&&bytes[2]==(byte)255)extension=".jpg";else if(new String(bytes,0,6,StandardCharsets.US_ASCII).matches("GIF8[79]a"))extension=".gif";else if(new String(bytes,0,4,StandardCharsets.US_ASCII).equals("RIFF")&&new String(bytes,8,4,StandardCharsets.US_ASCII).equals("WEBP"))extension=".webp";else if(new String(bytes,4,4,StandardCharsets.US_ASCII).equals("ftyp"))extension=".mp4";else if(bytes[0]==26&&bytes[1]==69&&bytes[2]==(byte)223&&bytes[3]==(byte)163)extension=".webm";}if(extension.isEmpty()||kind.equals("video")!=List.of(".mp4",".webm").contains(extension)||bytes.length>(kind.equals("video")?32:12)*1024*1024)throw new Exception("备份背景只支持常见图片（12 MiB 内）及 MP4/WebM（32 MiB 内）");return extension;}
    synchronized Object invoke(JSONObject args)throws Exception{
        if(!failure.isEmpty())throw new Exception(failure);
        switch(args.optString("operation")){
            case "backupInfo":{
                JSONObject appearance=runtime.store.object("appearance"),background=appearance==null?null:appearance.optJSONObject("background"),saved=readJournal();long bytes=0;if(background!=null)try{bytes=ownedBackground(background.optString("url")).length();}catch(Exception ignored){}
                JSONObject info=Json.obj("undoAvailable",saved!=null&&!saved.optBoolean("pending")&&!saved.optBoolean("recovered")&&!saved.optBoolean("blockedUndo")&&!saved.optBoolean("finishedUndo"),"backgroundBytes",bytes,"statsBytes",context.getDatabasePath("listening-stats.db").length(),"profileBytes",runtime.store.object("profile").toString().getBytes(StandardCharsets.UTF_8).length,"metadataBytes",runtime.store.object("personal").toString().getBytes(StandardCharsets.UTF_8).length,"backgroundKind",background==null?JSONObject.NULL:background.optString("kind"));
                if(saved!=null&&(saved.optBoolean("pending")||saved.optBoolean("recovered")||saved.optBoolean("browserPending")))Json.put(info,"recovery",recovery(saved));return info;
            }
            case "backupDiscard":pending=null;token=null;return true;
            case "backupApply":synchronized(stats){return runtime.store.backupLocked(()->{
                if(readJournal()!=null&&(readJournal().optBoolean("pending")||readJournal().optBoolean("recovered")||readJournal().optBoolean("browserPending")))throw new Exception("请先完成上次设置恢复回执");if(pending==null||!args.optString("token").equals(token))throw new Exception("恢复预览已失效，请重新选择备份");Set<String> selected=sections(args.optJSONArray("sections"));JSONObject before=capture(selected);if(selected.contains("featureSettings")){Json.put(before,"featureSettings",captureSettings(args.optJSONObject("browser")));Json.put(before,"browser",Json.obj("settings",args.optJSONObject("browser")==null?new JSONObject():args.getJSONObject("browser").optJSONObject("settings")));}JSONObject after=Json.copy(before),merged=BackupFormat.mergePersonal(before.getJSONObject("personal"),pending.getJSONObject("personal"),selected,runtime.store.array("localTracks"));Json.put(after,"personal",merged.getJSONObject("personal"));if(selected.contains("personalFeatures")&&pending.optJSONObject("extensions")!=null&&pending.getJSONObject("extensions").has("personalFeatures"))Json.put(after,"personalFeatures",PersonalFeatureFormat.merge(before.getJSONObject("personalFeatures"),pending.getJSONObject("extensions").getJSONObject("personalFeatures")));
                if(selected.contains("featureSettings")&&pending.optJSONObject("extensions")!=null&&pending.getJSONObject("extensions").has("featureSettings")){JSONObject settings=FeatureSettingsFormat.merge(before.getJSONObject("featureSettings"),pending.getJSONObject("extensions").getJSONObject("featureSettings"),args.optString("featureSettingsMode").equals("replace"));Json.put(after,"featureSettings",settings);Json.put(after,"browser",Json.obj("settings",settings));}if(selected.contains("profile")&&pending.has("profile")){JSONObject profile=Json.copy(before.getJSONObject("profile")),incoming=pending.getJSONObject("profile");for(Iterator<String> keys=incoming.keys();keys.hasNext();){String key=keys.next();Json.put(profile,key,incoming.opt(key));}if(!incoming.has("bio")&&incoming.has("tagline"))Json.put(profile,"bio",incoming.opt("tagline"));Json.put(after,"profile",profile);}
                if(selected.contains("stats")&&pending.has("stats"))Json.put(after,"stats",BackupFormat.mergeStats(before.getJSONObject("stats"),pending.getJSONObject("stats")));
                if(selected.contains("appearance")&&pending.has("appearance")){JSONObject value=pending.getJSONObject("appearance"),appearance=Json.copy(before.getJSONObject("appearance")),media=value.optJSONObject("media");Json.put(after.getJSONObject("profile"),"cardTransparency",value.optDouble("transparency"));Json.put(appearance,"transparency",value.optDouble("transparency"));if(media!=null){byte[] bytes=Base64.decode(media.getString("base64"),Base64.DEFAULT);String extension=media(bytes,media.getString("kind"));File directory=new File(context.getFilesDir(),"background");directory.mkdirs();File file=new File(directory,"backdrop-"+UUID.randomUUID()+extension);try(FileOutputStream output=new FileOutputStream(file)){output.write(bytes);}Json.put(appearance,"background",Json.obj("kind",media.getString("kind"),"name",media.getString("name"),"url",file.getAbsolutePath()));Json.put(appearance,"completed",true);}Json.put(after,"appearance",appearance);}
                JSONObject saved=Json.obj("pending",true,"before",before,"after",after,"sections",new JSONArray(selected));if(selected.contains("featureSettings"))Json.put(saved,"receiptId",UUID.randomUUID().toString());writeJournal(saved);
                try{writeState(after,selected);Json.put(saved,"pending",false);Json.put(saved,"browserPending",selected.contains("featureSettings"));writeJournal(saved);}catch(Exception e){try{writeState(before,selected);journal.delete();}catch(Exception rollback){failure="恢复中断，快照已保留；请重启后解决存储问题";runtime.store.stopWrites(failure);}throw e;}
                pending=null;token=null;runtime.emit();merged.remove("personal");Json.put(merged,"undoAvailable",true);if(selected.contains("featureSettings")){Json.put(merged,"browser",after.getJSONObject("browser"));Json.put(merged,"previousBrowser",before.getJSONObject("browser"));Json.put(merged,"sections",browserSections(selected));Json.put(merged,"browserReceipt",true);Json.put(merged,"receiptId",saved.optString("receiptId"));}return merged;
            });}
            case "backupRecover":synchronized(stats){return runtime.store.backupLocked(()->{
                JSONObject saved=readJournal();if(saved==null||!saved.optBoolean("pending")||!saved.optString("receiptId").equals(args.optString("receiptId")))throw new Exception("待处理恢复已变化，未修改当前资料");Set<String> chosen=sections(saved.getJSONArray("sections"));JSONObject current=capture(chosen);if(chosen.contains("featureSettings")){Json.put(current,"featureSettings",captureSettings(args.optJSONObject("browser")));Json.put(current,"browser",args.optJSONObject("browser"));}
                JSONObject observed=recoveryValues(current,chosen),before=recoveryValues(saved.getJSONObject("before"),chosen),after=recoveryValues(saved.getJSONObject("after"),chosen);for(Iterator<String> keys=observed.keys();keys.hasNext();){String key=keys.next(),value=BackupFormat.canonical(observed.get(key));if(!value.equals(BackupFormat.canonical(before.get(key)))&&!value.equals(BackupFormat.canonical(after.get(key))))throw new Exception("检测到恢复之后的新修改，当前资料已保留；请选择保留当前资料结束恢复");}
                JSONObject target=Json.copy(saved.getJSONObject("before"));if(chosen.contains("featureSettings")){JSONObject settings=target.getJSONObject("featureSettings");Json.put(settings.getJSONObject("space"),"revision",current.getJSONObject("featureSettings").getJSONObject("space").optLong("revision")+1);settings=FeatureSettingsFormat.clean(settings);Json.put(target,"featureSettings",settings);Json.put(target,"browser",Json.obj("settings",settings));}
                JSONObject recovery=Json.copy(saved);Json.put(recovery,"before",current);Json.put(recovery,"after",target);Json.put(recovery,"pending",true);Json.put(recovery,"recovered",false);Json.put(recovery,"blockedUndo",true);Json.put(recovery,"receiptId",UUID.randomUUID().toString());writeJournal(recovery);
                try{writeState(target,chosen);if(chosen.contains("featureSettings")){Json.put(recovery,"pending",false);Json.put(recovery,"browserPending",true);Json.put(recovery,"finishedUndo",true);writeJournal(recovery);}else journal.delete();}catch(Exception error){writeState(current,chosen);writeJournal(saved);throw error;}
                runtime.emit();return Json.obj("browser",target.optJSONObject("browser"),"previousBrowser",current.optJSONObject("browser"),"sections",browserSections(chosen),"browserReceipt",chosen.contains("featureSettings"),"receiptId",recovery.optString("receiptId"),"undoAvailable",false);
            });}
            case "backupKeepCurrent":synchronized(stats){return runtime.store.backupLocked(()->{
                JSONObject saved=readJournal();if(saved==null||!saved.optString("receiptId").equals(args.optString("receiptId")))throw new Exception("恢复回执已失效，当前设置已保留");
                Set<String> chosen=sections(saved.getJSONArray("sections"));JSONObject current=capture(chosen);if(chosen.contains("featureSettings"))Json.put(current,"featureSettings",captureSettings(args.optJSONObject("browser")));Json.put(current,"browser",args.optJSONObject("browser"));Json.put(saved,"after",current);Json.put(saved,"pending",false);Json.put(saved,"browserPending",false);Json.put(saved,"recovered",false);Json.put(saved,"finishedUndo",false);Json.put(saved,"blockedUndo",true);writeJournal(saved);return Json.obj("undoAvailable",false);
            });}
            case "backupAcknowledge":return runtime.store.backupLocked(()->{
                JSONObject saved=readJournal();if(saved==null)return true;if(saved.optBoolean("pending"))throw new Exception("后端恢复尚未完成，请明确选择恢复到操作前或保留当前资料");if(!saved.optString("receiptId").equals(args.optString("receiptId")))throw new Exception("恢复回执已失效，当前设置已保留");
                JSONObject desired=recovery(saved),browser=args.optJSONObject("browser"),expected=desired.getJSONObject("browser");
                if(browser==null||!BackupFormat.canonical(FeatureSettingsFormat.renderer(browser.optJSONObject("settings"))).equals(BackupFormat.canonical(FeatureSettingsFormat.renderer(expected.optJSONObject("settings")))))throw new Exception("界面设置尚未完成写入，恢复快照仍保留");
                if(saved.optBoolean("finishedUndo")||saved.optBoolean("recovered")&&saved.optString("recoveryTarget").equals("before"))journal.delete();else{Json.put(saved,"browserPending",false);Json.put(saved,"recovered",false);writeJournal(saved);}return true;
            });
            case "backupUndo":synchronized(stats){return runtime.store.backupLocked(()->{
                JSONObject saved=readJournal();if(saved==null||saved.optBoolean("pending")||saved.optBoolean("recovered")||saved.optBoolean("blockedUndo"))throw new Exception("没有可撤销的恢复，当前资料及原快照已保留");Set<String> chosen=sections(saved.getJSONArray("sections"));JSONObject current=capture(chosen);if(chosen.contains("featureSettings"))Json.put(current,"featureSettings",captureSettings(args.optJSONObject("browser")));
                if(!BackupFormat.canonical(selected(current,chosen)).equals(BackupFormat.canonical(selected(saved.getJSONObject("after"),chosen))))throw new Exception("恢复后资料已改变，暂不能整体撤销，以免覆盖新资料；恢复前快照仍保留");
                JSONObject target=Json.copy(saved.getJSONObject("before"));if(chosen.contains("featureSettings")){Json.put(target.getJSONObject("featureSettings").getJSONObject("space"),"revision",current.getJSONObject("featureSettings").getJSONObject("space").optLong("revision")+1);Json.put(target,"browser",Json.obj("settings",target.getJSONObject("featureSettings")));}
                JSONObject undo=Json.copy(saved);Json.put(undo,"pending",true);Json.put(undo,"before",current);if(chosen.contains("featureSettings"))Json.put(undo,"receiptId",UUID.randomUUID().toString());writeJournal(undo);
                try{writeState(target,chosen);if(chosen.contains("featureSettings")){Json.put(undo,"pending",false);Json.put(undo,"browserPending",true);Json.put(undo,"after",target);Json.put(undo,"finishedUndo",true);writeJournal(undo);}else journal.delete();}catch(Exception e){writeState(current,chosen);writeJournal(saved);throw e;}
                runtime.emit();return chosen.contains("featureSettings")?Json.obj("undoAvailable",false,"browser",target.getJSONObject("browser"),"previousBrowser",Json.obj("settings",args.optJSONObject("browser")==null?current.getJSONObject("featureSettings"):args.getJSONObject("browser").optJSONObject("settings")),"sections",browserSections(chosen),"browserReceipt",true,"receiptId",undo.optString("receiptId")):Json.obj("undoAvailable",false);
            });}
            case "backupRelink":synchronized(stats){return runtime.store.backupLocked(()->{JSONObject personal=runtime.store.object("personal");int[] count={0};relink(personal,runtime.store.array("localTracks"),count);runtime.store.replaceAtomic(Json.obj("personal",personal));runtime.emit();return Json.obj("linked",count[0]);});}
            default:throw new Exception("未知资料备份操作");
        }
    }
    private void relink(Object value,JSONArray local,int[] count)throws Exception{if(value instanceof JSONArray){JSONArray array=(JSONArray)value;for(int i=0;i<array.length();i++){Object child=array.get(i);JSONObject song=child instanceof JSONObject?(JSONObject)child:null;if(song!=null&&song.has("title")&&song.optString("source").equals("local")&&song.optString("availability").equals("unavailable")){JSONObject restored=BackupFormat.restoreTrack(song,local);if(restored.optString("availability").equals("playable"))count[0]++;array.put(i,restored);}else relink(child,local,count);}}else if(value instanceof JSONObject){JSONObject object=(JSONObject)value;for(Iterator<String> keys=object.keys();keys.hasNext();){String key=keys.next();Object child=object.get(key);if(key.equals("track")&&child instanceof JSONObject){JSONObject song=(JSONObject)child;if(song.optString("source").equals("local")&&song.optString("availability").equals("unavailable")){JSONObject restored=BackupFormat.restoreTrack(song,local);if(restored.optString("availability").equals("playable"))count[0]++;Json.put(object,key,restored);if(object.has("playedAt"))Json.put(object,"id",restored.optString("id"));}else relink(child,local,count);}else relink(child,local,count);}}}
}
